CREATE TABLE IF NOT EXISTS products(id BIGINT PRIMARY KEY, name VARCHAR(100) NOT NULL, price BIGINT NOT NULL CHECK(price>0), stock INTEGER NOT NULL CHECK(stock>=0));
CREATE TABLE IF NOT EXISTS reservations(order_id UUID PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL, amount BIGINT NOT NULL, released BOOLEAN NOT NULL DEFAULT FALSE);
INSERT INTO products(id,name,price,stock) SELECT 1,'MiniMart milk',25000,1000 WHERE NOT EXISTS (SELECT 1 FROM products WHERE id=1);
